def signature(md, body, address):
    """Instruction text with image addresses blanked: equal for the same code at another address."""
    def blank(m):
        v = int(m.group(0), 16)
        return f'+{v - address:x}' if address <= v < address + len(body) else '#'
    out = []
    for insn in md.disasm(body, address):
        out.append(insn.mnemonic + ' ' + re.sub(r'0x[0-9a-f]{6,}', blank, insn.op_str))
    return '\n'.join(out)


def transfer(target, entries, lifted_root):
    """{address: (name, evidence)} for target: its own table, plus names of the
    other target's table where exactly one function here has the same code."""
    own = {a: v for a, v in KNOWN.get(target, {}).items()}
    md = Cs(CS_ARCH_X86, CS_MODE_32)
    here = {}
    for e in entries:
        a = int(e['address'], 16)
        here.setdefault(signature(md, bytes.fromhex(e['native_body']), a), []).append(a)
    for other, table in KNOWN.items():
        if other == target or not table: continue
        path = lifted_root / other / 'catalog.json'
        if not path.exists(): continue
        theirs = {int(e['address'], 16): e for e in json.loads(path.read_text())['entries']}
        for a, (name, why) in table.items():
            if a not in theirs: continue
            sig = signature(md, bytes.fromhex(theirs[a]['native_body']), a)
            match = here.get(sig, [])
            if len(match) == 1 and match[0] not in own:
                own[match[0]] = (name, f'same code as {other} 0x{a:08x}: {why}')
    return own


def transfer_globals(target, entries, lifted_root):
    """{address: (name, evidence)} of hand-identified globals for target: its
    own table, plus globals of the other target's table that functions with the
    same code use at the same instruction (only when every use agrees)."""
    own = dict(GLOBALS.get(target, {}))
    md = Cs(CS_ARCH_X86, CS_MODE_32)
    here = {}
    for e in entries:
        a = int(e['address'], 16)
        here.setdefault(signature(md, bytes.fromhex(e['native_body']), a), []).append(e)
    for other, table in GLOBALS.items():
        if other == target or not table: continue
        path = lifted_root / other / 'catalog.json'
        if not path.exists(): continue
        found = {}
        for e in json.loads(path.read_text())['entries']:
            a, body = int(e['address'], 16), bytes.fromhex(e['native_body'])
            if not any(g.to_bytes(4, 'little') in body for g in table): continue
            match = here.get(signature(md, body, a), [])
            if len(match) != 1: continue
            m = match[0]
            for x, y in zip(md.disasm(body, a), md.disasm(bytes.fromhex(m['native_body']), int(m['address'], 16))):
                for gx, gy in zip(re.findall(r'0x[0-9a-f]{6,}', x.op_str), re.findall(r'0x[0-9a-f]{6,}', y.op_str)):
                    if int(gx, 16) in table: found.setdefault(int(gx, 16), set()).add(int(gy, 16))
        for g, ys in found.items():
            if len(ys) == 1 and (y := next(iter(ys))) not in own:
                name, why = table[g]
                own[y] = (name, f'same use as {other} 0x{g:08x}: {why}')
    return own
